spec.setup_code:
var A = new api.THREE.Vector3(2, 0, 0);
var origin = new api.THREE.Vector3(0, 0, 0);
var arrowA = new api.THREE.ArrowHelper(A.clone().normalize(), origin, A.length(), 0x4C72B0);
var arrowB = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 1.5, 0xE8593C);
var arrowProj = new api.THREE.ArrowHelper(new api.THREE.Vector3(1, 0, 0), origin, 0.1, 0x2E7D32);
api.group.add(arrowA);
api.group.add(arrowB);
api.group.add(arrowProj);
return {
  update: function(t) {
    var theta = (t * 0.005) % (Math.PI * 2);
    var B = new api.THREE.Vector3(1.5 * Math.cos(theta), 1.5 * Math.sin(theta), 0);
    arrowB.setDirection(B.clone().normalize());
    arrowB.setLength(Math.max(B.length(), 0.01));
    var scalarProj = B.dot(A) / A.length();
    var dir = scalarProj >= 0 ? A.clone().normalize() : A.clone().normalize().negate();
    arrowProj.setDirection(dir);
    arrowProj.setLength(Math.max(Math.abs(scalarProj), 0.01));
  }
};

return {
  draw: function(ctx, W, H, t, dt) {
    ctx.fillStyle = '#F5F0E8';
    ctx.fillRect(0, 0, W, H);
    function arrow(x0, y0, x1, y1, color) {
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 3;
      ctx.beginPath();
      ctx.moveTo(x0, y0);
      ctx.lineTo(x1, y1);
      ctx.stroke();
      var ang = Math.atan2(y1 - y0, x1 - x0);
      var hs = 10;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x1 - hs * Math.cos(ang - Math.PI / 6), y1 - hs * Math.sin(ang - Math.PI / 6));
      ctx.lineTo(x1 - hs * Math.cos(ang + Math.PI / 6), y1 - hs * Math.sin(ang + Math.PI / 6));
      ctx.closePath();
      ctx.fill();
    }
    var scale = Math.min(W, H) * 0.015;
    var ox = W * 0.3, oy = H * 0.6;
    var Amag = 5, Bmag = 4;
    var theta = (t * 0.005) % (Math.PI * 2);
    arrow(ox, oy, ox + Amag * scale, oy, '#4C72B0');
    var bx = Bmag * scale * Math.cos(theta), by = -Bmag * scale * Math.sin(theta);
    arrow(ox, oy, ox + bx, oy + by, '#E8593C');
    var proj = Bmag * Math.cos(theta);
    ctx.setLineDash([4, 4]);
    ctx.strokeStyle = '#999999';
    ctx.beginPath();
    ctx.moveTo(ox + bx, oy + by);
    ctx.lineTo(ox + proj * scale, oy);
    ctx.stroke();
    ctx.setLineDash([]);
    arrow(ox, oy, ox + proj * scale, oy, '#2E7D32');
    var dot = Amag * Bmag * Math.cos(theta);
    ctx.fillStyle = '#333';
    ctx.font = '16px sans-serif';
    ctx.fillText('A . B = |A||B|cos(theta) = ' + dot.toFixed(1), ox - 20, oy + 50);
  }
};
